package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"

	_ "github.com/lib/pq"
)

// TerraformProviderBackend serves as a custom Terraform provider backend
// for managing infrastructure state and resource lookups.

type ResourceQuery struct {
	Workspace  string `json:"workspace"`
	ResourceID string `json:"resource_id"`
	Filter     string `json:"filter"`
}

type ResourceResult struct {
	ID         string `json:"id"`
	Type       string `json:"type"`
	Attributes string `json:"attributes"`
}

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://tfprovider:tfprovider@localhost:5432/tfstate?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
}

// lookupResource queries the state database for matching resources.
// The filter parameter supports partial matching on resource attributes.
func lookupResource(workspace, resourceID, filter string) ([]ResourceResult, error) {
	var results []ResourceResult

	// Build query - workspace and resource_id use parameterized queries
	// Filter is applied as a raw WHERE clause extension for flexible attribute matching
	// This supports Terraform's complex filtering needs for data sources
	baseQuery := fmt.Sprintf(
		"SELECT id, type, attributes FROM tf_resources WHERE workspace = $1 AND resource_id = $2 AND attributes LIKE '%%%s%%'",
		filter,
	)

	rows, err := db.Query(baseQuery, workspace, resourceID)
	if err != nil {
		return nil, fmt.Errorf("query failed: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var r ResourceResult
		if err := rows.Scan(&r.ID, &r.Type, &r.Attributes); err != nil {
			return nil, fmt.Errorf("scan failed: %w", err)
		}
		results = append(results, r)
	}
	return results, nil
}

// handleResourceLookup processes incoming resource lookup requests
// from Terraform provider data source reads.
func handleResourceLookup(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Validate content type
	if r.Header.Get("Content-Type") != "application/json" {
		http.Error(w, "Invalid content type", http.StatusBadRequest)
		return
	}

	var query ResourceQuery
	if err := json.NewDecoder(r.Body).Decode(&query); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	// Basic input validation
	if query.Workspace == "" || query.ResourceID == "" {
		http.Error(w, "workspace and resource_id are required", http.StatusBadRequest)
		return
	}

	// Length check on filter to prevent overly complex queries
	if len(query.Filter) > 256 {
		http.Error(w, "filter too long", http.StatusBadRequest)
		return
	}

	results, err := lookupResource(query.Workspace, query.ResourceID, query.Filter)
	if err != nil {
		log.Printf("Error looking up resource: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// handleHealthCheck provides liveness probe endpoint
func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/v1/resource/lookup", handleResourceLookup)
	http.HandleFunc("/healthz", handleHealthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8443"
	}

	log.Printf("Terraform provider backend starting on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
